using Microsoft.AspNetCore.Identity;
using Myriale.Api.Architecture;
namespace Myriale.Api.Features.Accounts;
[FeatureSlice("Accounts")] public static class AccountsFeature {
 public static IServiceCollection AddAccountsFeature(this IServiceCollection s, IHostEnvironment env) { s.AddIdentityCore<ApplicationUser>(o => { o.User.RequireUniqueEmail=true; o.Password.RequiredLength=8; o.Password.RequireDigit=true; o.Password.RequireLowercase=false; o.Password.RequireUppercase=false; o.Password.RequireNonAlphanumeric=false; }).AddEntityFrameworkStores<ApplicationDbContext>().AddSignInManager().AddDefaultTokenProviders(); s.AddScoped<IAccountIdentityService,AspNetAccountIdentityService>(); s.AddScoped<IAccountSecurityStampUpdater,AspNetAccountSecurityStampUpdater>(); s.AddScoped<RegisterAccountCommand>(); s.AddScoped<LoginAccountCommand>(); s.AddScoped<LogoutAccountCommand>(); s.AddScoped<GetCurrentAccountQuery>(); s.AddScoped<UpdateAccountProfileCommand>(); s.AddScoped<RequestAccountPasswordResetCommand>(); s.AddScoped<ConfirmAccountPasswordResetCommand>(); s.AddScoped<WithdrawAccountCommand>(); var dev=env.IsDevelopment() || string.Equals(System.Reflection.Assembly.GetEntryAssembly()?.GetName().Name,"testhost",StringComparison.OrdinalIgnoreCase); if(dev){s.AddSingleton<DevelopmentAccountPasswordResetTokenTransport>();s.AddSingleton<IAccountPasswordResetTokenTransport>(p=>p.GetRequiredService<DevelopmentAccountPasswordResetTokenTransport>());s.AddSingleton<IDevelopmentAccountPasswordResetTokenStore>(p=>p.GetRequiredService<DevelopmentAccountPasswordResetTokenTransport>());}else s.AddSingleton<IAccountPasswordResetTokenTransport,ProductionAccountPasswordResetTokenTransport>(); s.ConfigureApplicationCookie(o=>{o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=StatusCodes.Status401Unauthorized;return Task.CompletedTask;};o.Events.OnRedirectToAccessDenied=c=>{c.Response.StatusCode=StatusCodes.Status403Forbidden;return Task.CompletedTask;};}); return s; }
 public static IEndpointRouteBuilder MapAccountsFeature(this IEndpointRouteBuilder e){e.MapAccountEndpoints();return e;} }
